import pandas as pd

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")
    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Deduplicate events by seq (keep first occurrence)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort events by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Build initial state dict from target_state
    state = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders had a row at any point (for tombstones logic)
    orders_ever_existed = set(state.keys())

    # Track last operation per order for tombstones
    last_op_per_order = {}

    # Step 4: Apply events in seq order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists and seq <= last_seq
        if order_id in state and seq <= state[order_id]["last_seq"]:
            continue

        # Apply the event
        if op in ("I", "U"):
            if order_id in state:
                # Update existing row
                # For UPDATE: NULL amount means keep existing amount
                if pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    state[order_id]["amount"] = amount
                state[order_id]["status"] = status
            else:
                # Create new row (both I and U can create if missing)
                state[order_id] = {
                    "status": status,
                    "amount": amount
                }
                orders_ever_existed.add(order_id)

            state[order_id]["last_seq"] = seq
            last_op_per_order[order_id] = op

        elif op == "D":
            # Delete: remove the row if it exists
            if order_id in state:
                del state[order_id]
            last_op_per_order[order_id] = op

    # Step 5: Build new_state output
    new_state_rows = []
    for order_id, row_data in state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": row_data["status"],
            "amount": row_data["amount"],
            "last_seq": row_data["last_seq"]
        })

    if new_state_rows:
        new_state_df = pd.DataFrame(new_state_rows)
    else:
        new_state_df = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Step 6: Build tombstones output
    # Tombstones: orders that ever existed and whose last applied event was 'D'
    tombstone_rows = []
    for order_id in orders_ever_existed:
        # Only create tombstone if last operation was 'D' and order is not currently in state
        if order_id in last_op_per_order and last_op_per_order[order_id] == "D":
            if order_id not in state:  # Confirm order is actually deleted
                # Find the seq of the last 'D' event for this order
                order_events = cdc_events[cdc_events["order_id"] == order_id]
                delete_events = order_events[order_events["op"] == "D"]
                if not delete_events.empty:
                    last_delete_seq = delete_events.iloc[-1]["seq"]
                    tombstone_rows.append({
                        "order_id": order_id,
                        "deleted_seq": last_delete_seq
                    })

    if tombstone_rows:
        tombstones_df = pd.DataFrame(tombstone_rows)
    else:
        tombstones_df = pd.DataFrame(columns=["order_id", "deleted_seq"])

    # Ensure correct dtypes
    if not new_state_df.empty:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")

    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")

    return {
        "new_state": new_state_df,
        "tombstones": tombstones_df
    }
